#include "ApprovalDocument.h"
#include "Paths.h"
#include "protocol-v3.hpp"
#include <QDateTime>
#include <QStringDecoder>
void ApprovalDocument::invalidate(){file_.reset();manifest_={};hash_.reset();offset_=size_=cacheBytes_=0;complete_=verified_=current_=displayed_=false;pages_.clear();lru_.clear();offsets_.clear();lengths_.clear();identity_.clear();emit changed();}
bool ApprovalDocument::fail(){invalidate();return false;}
bool ApprovalDocument::begin(const QJsonObject&m,const QString&cid){invalidate();const QJsonObject frame{{"v",3},{"id","manifest"},{"epoch","validation"},{"ok",true},{"result",m}};if(!TildeProtocolV3::validateServerFrame(frame)||m.value("conversationId")!=cid||!m.contains("operationId")||m.value("bytes").toInteger()<1||m.value("bytes").toInteger()>67108864||m.value("expiresAt").toInteger()<=QDateTime::currentMSecsSinceEpoch()||!PrivatePaths::directory(directory_,true))return false;file_=std::make_unique<QTemporaryFile>(directory_+"/review-XXXXXX");if(!file_->open()||!file_->setPermissions(QFileDevice::ReadOwner|QFileDevice::WriteOwner))return fail();const auto cachePath=file_->fileName();if(cachePath.isEmpty())return fail();manifest_=m;size_=m.value("bytes").toInteger();current_=true;emit changed();return true;}
bool ApprovalDocument::canApprove()const{return complete_&&verified_&&current_&&displayed_&&manifest_.value("expiresAt").toInteger()>QDateTime::currentMSecsSinceEpoch()&&!identity_.isEmpty()&&identity()==identity_;}
void ApprovalDocument::setDisplayed(bool value){const bool next=value&&current_&&verified_&&complete_;if(next==displayed_)return;displayed_=next;emit changed();}
void ApprovalDocument::setCurrent(bool value){if(!value)invalidate();}
bool ApprovalDocument::acceptChunk(const QJsonObject&chunk){if(!file_||!current_||complete_||manifest_.value("expiresAt").toInteger()<=QDateTime::currentMSecsSinceEpoch())return fail();const QJsonObject frame{{"v",3},{"id","chunk"},{"epoch","validation"},{"ok",true},{"result",chunk}};if(!TildeProtocolV3::validateServerFrame(frame)||chunk.value("payloadId")!=manifest_.value("payloadId")||chunk.value("offset").toInteger(-1)!=offset_||!chunk.value("text").isString())return fail();const auto text=chunk.value("text").toString();const auto bytes=text.toUtf8();if(QString::fromUtf8(bytes)!=text||bytes.isEmpty()||bytes.size()>32768||offset_+bytes.size()>size_)return fail();const auto end=offset_+bytes.size();if(end<size_?chunk.value("nextOffset").toInteger(-1)!=end:chunk.contains("nextOffset"))return fail();if(file_->write(bytes)!=bytes.size())return fail();offsets_.append(offset_);lengths_.append(bytes.size());hash_.addData(bytes);offset_=end;if(offset_==size_){if(!file_->flush()||QString::fromLatin1(hash_.result().toHex())!=manifest_.value("sha256").toString())return fail();identity_=identity();if(identity_.isEmpty())return fail();complete_=verified_=true;}emit changed();return true;}
QString ApprovalDocument::page(qint64 offset,int max){if(!verified_||!current_||!file_||offset<0||offset>=size_||max<1||max>32768)return {};if(identity_.isEmpty()||identity()!=identity_)return fail(),QString();if(pages_.contains(offset)&&pages_.value(offset).size()<=max){lru_.removeAll(offset);lru_.append(offset);return QString::fromUtf8(pages_.value(offset));}if(!file_->seek(offset))return fail(),QString();const auto expected=qMin(qint64(max),size_-offset);auto bytes=file_->read(expected);if(bytes.size()!=expected||file_->error()!=QFileDevice::NoError||identity()!=identity_)return fail(),QString();QString text;bool valid=false;for(int trim=0;trim<=3&&trim<bytes.size();trim++){QStringDecoder decoder(QStringDecoder::Utf8);text=decoder.decode(bytes.first(bytes.size()-trim));if(!decoder.hasError()){bytes.chop(trim);valid=true;break;}}if(!valid)return {};if(pages_.contains(offset))cacheBytes_-=pages_.take(offset).size();pages_[offset]=bytes;lru_.removeAll(offset);lru_.append(offset);cacheBytes_+=bytes.size();while(cacheBytes_>1024*1024||lru_.size()>32){const auto oldest=lru_.takeFirst();cacheBytes_-=pages_.take(oldest).size();}return text;}

QByteArray ApprovalDocument::identity()const{if(!file_)return {};struct stat s{};if(fstat(file_->handle(),&s)!=0||!S_ISREG(s.st_mode)||s.st_nlink!=1||s.st_uid!=geteuid()||(s.st_mode&0077)||s.st_size!=size_)return {};return QByteArray::number(qulonglong(s.st_dev))+":"+QByteArray::number(qulonglong(s.st_ino))+":"+QByteArray::number(s.st_size)+":"+QByteArray::number(s.st_mtim.tv_sec)+":"+QByteArray::number(s.st_mtim.tv_nsec)+":"+QByteArray::number(s.st_ctim.tv_sec)+":"+QByteArray::number(s.st_ctim.tv_nsec);}
QString ApprovalDocument::pageAt(int index){if(index<0||index>=pageCount())return {};return page(offsets_[index],int(lengths_[index]));}
